import {renderTactics,renderTacticalResult,tacticalPayload,tacticsClick,tacticsChange} from '/tactics-ui.mjs';
import {audioState,setAudio,unlockAudio,updateAudio,effect} from '/audio.mjs';
import {getRank,rankLabel,rankHtml,rankPercent,applyRankResult} from '/rank.mjs';
import {PLAYERS,ROLES,STYLES,createRoom,action,tick,publicState,catalog,maxBid,compBonus,DEFAULT_CONFIG,marketSize,standings} from '/engine.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const TEAM={FUR:'FURIA',LOS:'LOS',LLL:'LOUD',PNG:'paiN Gaming',RED:'RED Canids',KST:'Keyd Stars',FX:'Fluxo W7M',LEV:'LEVIATÁN'};
const TEAMCOL={FUR:['#e7eae4','#4e564b'],LOS:['#f9e4d0','#ab6c3c'],LLL:['#e6efcf','#668737'],PNG:['#f1e2df','#9a6256'],RED:['#f5e4e1','#a6574d'],KST:['#e9e1f0','#846298'],FX:['#e2eae3','#52755c'],LEV:['#e0ebee','#507b89']};
let lastPhase=null;let roomConfig={...DEFAULT_CONFIG};let selectedComp=null;
let room=null,raw=null,myId=null,token=null,local=false,busy=false,capacity=4,offset=0,signature='',catalogRole='ALL',search='',lastLog=0,polling=false,sounds=false;
const ORIGINAL_RATINGS=new Map(PLAYERS.map(p=>[p.id,{...p}]));
function syncRatings(s){for(const p of PLAYERS){const shown=catalog.get(p.id);if(shown)Object.assign(shown,ORIGINAL_RATINGS.get(p.id),s?.ratingOverrides?.[p.id]||{});}}
const store={get(k){try{return JSON.parse(localStorage.getItem(k));}catch{return null;}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));}catch{}}};
const initials=s=>s.slice(0,2).toUpperCase();const now=()=>Date.now()+offset;const style=id=>STYLES.find(x=>x.id===id);const me=()=>room?.members.find(m=>m.id===myId);const isHost=()=>room?.host===myId;
function toast(s,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=s;$('toasts').append(el);setTimeout(()=>el.remove(),4700);}
function beep(){if(!sounds)return;try{const ac=new AudioContext(),o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);g.gain.value=.025;o.frequency.value=540;o.start();g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.18);o.stop(ac.currentTime+.2);o.onended=()=>ac.close();}catch{}}
const champ=c=>`https://ddragon.leagueoflegends.com/cdn/16.22.1/img/champion/${encodeURIComponent(c)}.png`;
const champName=c=>({JarvanIV:'Jarvan IV',LeeSin:'Lee Sin',KSante:"K’Sante",AurelionSol:'Aurelion Sol',Khazix:"Kha’Zix",Kaisa:"Kai’Sa",Belveth:"Bel’Veth",XinZhao:'Xin Zhao',MissFortune:'Miss Fortune',MonkeyKing:'Wukong',TwistedFate:'Twisted Fate',Chogath:"Cho’Gath",RekSai:"Rek’Sai",Velkoz:"Vel’Koz",DrMundo:'Dr. Mundo',TahmKench:'Tahm Kench',Renata:'Renata Glasc',Nunu:'Nunu e Willump'}[c]||c);
const teamName=id=>room.members.find(m=>m.id===id)?.name||'A definir';

const FORMAT_NAMES={knockout:'Mata-mata',league:'Pontos corridos','league-playoffs':'Liga + playoffs','groups-playoffs':'Grupos + mata-mata'};
const SUPPLY_NAMES={exact:'Quantidade exata',exact12:'Exata + 12',all:'Todos os jogadores'};
const DRAFT_NAMES={mixed:'CBLOL + Worlds · sorteados',worlds:'Somente Worlds 2026',cblol:'Somente CBLOL 2026'};
const canEdit=()=>room&&(room.host===myId||room.editors?.includes(myId));
function refreshRankHeader(){const node=$('rankProfile');if(!node)return;const name=me()?.name||store.get('rift-name')||'Equipe';node.innerHTML=rankHtml(name);node.title='Perfil de ranqueada de '+name;}
const hiddenRatings=()=>room?.phase==='auction'&&room.config?.showOverall===false;
const photo=(p,cls='player-photo')=>`<img class="${cls}" src="${esc(p.photo||'/players/'+p.id+'.webp')}" alt="Foto de ${esc(p.name)}" loading="lazy">`;
function configControls(config,n,disabled=false){return `<div class="room-options"><label class="field">Como jogar<select id="gameplayMode" ${disabled?'disabled':''}><option value="automatic" ${config.gameplay!=='mechanical'?'selected':''}>Automático · simulação</option><option value="mechanical" ${config.gameplay==='mechanical'?'selected':''}>Mecânico · tática pausada</option></select><span class="field-note">Mecânico: mova os cinco campeões, compre itens e dispute objetivos com ordens simultâneas.</span></label><label class="field">Jogadores disponíveis<select id="supplyMode" ${disabled?'disabled':''}>${Object.entries(SUPPLY_NAMES).map(([key,label])=>`<option value="${key}" ${config.supply===key?'selected':''}>${label}</option>`).join('')}</select><span class="field-note" id="marketCount">${marketSize(n,config.supply)} cartas para ${n*5} vagas${config.supply==='exact12'&&n*5+12>PLAYERS.length?' · limitado ao catálogo de '+PLAYERS.length:''}</span></label><label class="field">Formato do campeonato<select id="formatMode" ${disabled?'disabled':''}>${Object.entries(FORMAT_NAMES).map(([key,label])=>`<option value="${key}" ${config.format===key?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Origem das composições<select id="draftPool" ${disabled?'disabled':''}>${Object.entries(DRAFT_NAMES).map(([key,label])=>`<option value="${key}" ${config.draftPool===key?'selected':''}>${label}</option>`).join('')}</select><span class="field-note">Cartas reais da CBLOL 2026 (playoffs) e do Worlds 2026. São 10 segundos por draft, com Fearless.</span></label><label class="check-setting"><input id="showOverall" type="checkbox" ${config.showOverall?'checked':''} ${disabled?'disabled':''}><span>Mostrar overall e atributos no leilão<small>Desligue para jogar com as notas ocultas até fechar os times.</small></span></label></div>`;}
function tableView(group=null){const rows=standings(room,group);return `<div class="table-scroll"><table class="data-table standings"><thead><tr><th>Equipe${group?' · Grupo '+group:''}</th><th>PTS</th><th>V</th><th>D</th><th>Jogos</th><th>Saldo</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${r.id===myId?'my-row':''}"><td><span class="rank">${i+1}</span>${esc(r.name)}</td><td><strong>${r.points}</strong></td><td>${r.wins}</td><td>${r.losses}</td><td>${r.gameWins}–${r.gameLosses}</td><td>${r.gameWins-r.gameLosses>0?'+':''}${r.gameWins-r.gameLosses}</td></tr>`).join('')}</tbody></table></div>`;}
function opponentLineups(){const match=room.matches[room.matchIndex];return `<details class="match-rosters"><summary>Line-ups deste confronto · ver as duas equipes</summary><div class="both-rosters">${[match.a,match.b].map(id=>rosterPanel(room.members.find(m=>m.id===id))).join('')}</div></details>`;}
function matchLabel(m){if(m.stage==='league')return 'Liga · rodada '+m.round;if(m.stage==='groups')return 'Grupo '+m.group+' · rodada '+m.round;const n=room.matches.filter(x=>(x.stage||'playoffs')==='playoffs'&&x.round===m.round).length*2;return n===2?'Grande final':n===4?'Semifinais':'Quartas de final';}

function stats(p){const hidden=hiddenRatings();return `<div class="stats"><div>MENTAL<b>${hidden?'?':p.mental}</b></div><div>MACRO<b>${hidden?'?':p.macro}</b></div><div>MICRO<b>${hidden?'?':p.micro}</b></div></div>`;}
function playerTile(p){const hidden=hiddenRatings();return `<button class="player-tile" data-player="${p.id}" aria-label="Ver carta de ${esc(p.name)}"><div class="tile-portrait">${photo(p)}<span class="portrait-role">${p.role}</span><span class="rating-num">${hidden?'?':p.overall}<small>OVR</small></span></div><strong class="player-name">${esc(p.name)}</strong><div class="player-meta">${esc(TEAM[p.team])} · ${p.role}</div>${stats(p)}<div class="player-bottom">${hidden?'Notas ocultas nesta sala':`<span class="coin">R</span>${p.price} valor de referência`}</div></button>`;}
function home(){signature='';syncRatings(null);refreshRankHeader();const invite=new URL(location.href).searchParams.get('sala')||'';const featured=['tatu','feisty','ayu','ceos'].map(id=>catalog.get(id));const last=store.get('rift-last');$('app').innerHTML=`<div class="pagehead"><div><div class="eyebrow">O PRÓXIMO CAMPEÃO COMEÇA NO DRAFT</div></div><span class="badge">Split 2 · Temporada 2026</span></div><section class="hero-grid"><div class="hero"><div class="hero-copy"><span class="badge">LEILÃO + ESTRATÉGIA + CBLOL</span><h1>Seu time.<br>Sua <em>chamada.</em></h1><p class="desc">Contrate os nomes do CBLOL. Encontre a composição. Leve sua tropa até a taça.</p></div><div class="hero-art" aria-hidden="true"><span class="hero-star">✧</span><div class="mini-card back"><span class="rating">${catalog.get('tatu').overall}</span><span class="card-role">JUNGLE</span><div class="card-face"><img src="/players/tatu.webp" alt=""></div><strong>Tatu</strong><div class="tiny-stats"><span>MENT<b>${catalog.get('tatu').mental}</b></span><span>MAC<b>${catalog.get('tatu').macro}</b></span><span>MIC<b>${catalog.get('tatu').micro}</b></span></div></div><div class="mini-card front"><span class="rating">${catalog.get('feisty').overall}</span><span class="card-role">MID LANE</span><div class="card-face"><img src="/players/feisty.webp" alt=""></div><strong>Feisty</strong><div class="tiny-stats"><span>MENT<b>${catalog.get('feisty').mental}</b></span><span>MAC<b>${catalog.get('feisty').macro}</b></span><span>MIC<b>${catalog.get('feisty').micro}</b></span></div></div><span class="hero-note">o último lance é seu.</span></div><div class="hero-details"><div><strong>50</strong><span>moedas para começar</span></div><div><strong>5</strong><span>posições. Um time.</span></div><div><strong>MD3</strong><span>dois jogos para vencer</span></div></div></div><form id="setupForm" class="setup"><div class="setup-head"><h2>Abra a sua sala.</h2><p class="muted" style="margin-top:7px">Chame a tropa. O resto é no Rift.</p></div><label class="field">Nome da sua equipe<input id="teamName" name="team" maxlength="24" autocomplete="nickname" placeholder="Ex.: Tropa do Baron" value="${esc(store.get('rift-name')||'')}" required></label><div class="field"><span>Equipes no campeonato</span><div class="capacity">${[2,4,8].map(n=>`<button type="button" data-capacity="${n}" class="${n===capacity?'selected':''}" aria-pressed="${n===capacity}">${n} equipes</button>`).join('')}</div><span class="field-note">Vagas livres podem ser preenchidas com bots.</span></div><details class="setup-config"><summary>Modo, mercado e formato<span>Configurar o campeonato</span></summary>${configControls(roomConfig,capacity)}</details><div class="setup-actions"><button class="btn primary wide" type="submit" id="createRoomBtn">Criar sala com amigos</button><button class="btn outline wide" type="button" data-action="practice">Treinar contra bots</button></div><div class="divider"></div><div class="setup-join"><label class="field" for="inviteCode">Já tem um convite?</label><div class="join-row" style="margin-top:8px"><input id="inviteCode" maxlength="180" placeholder="Código ou link da sala" value="${esc(invite)}" aria-label="Código ou link da sala"><button class="btn ghost" type="button" data-action="join">Entrar</button></div>${last?`<button type="button" class="text-btn" data-action="resume" style="margin-top:15px">Retomar última sala</button>`:''}</div></form></section><div class="section-title"><h3>Quem vai vestir sua camisa?</h3><button class="text-btn" data-action="catalog">Explorar as 43 cartas</button></div><div class="home-cards">${featured.map(playerTile).join('')}</div><p class="help-note">Fotos reais. Atributos balanceados com desempenho individual e coletivo. Composições reais do CBLOL e Worlds 2026. Inspirado em Footlobby.</p>`;}
function shell(){const phase={lobby:'Sala de espera',auction:'Leilão',tournament:'Campeonato',finished:'Campeonato encerrado'}[room.phase];return `<div class="pagehead"><div><span class="eyebrow">${local?'TREINO LOCAL':'SALA '+room.code} · ${FORMAT_NAMES[room.config?.format]||'Mata-mata'}</span><h2>${phase}</h2></div><div class="pagehead-right">${local?'<span class="badge local">Você + bots · neste aparelho</span>':'<button class="btn small outline" data-action="copy">Copiar convite</button>'}<button class="btn small ghost" data-action="teams">Equipes</button><button class="btn small ghost" data-action="market" ${room.phase!=='auction'?'hidden':''}>Mercado</button>${canEdit()&&['lobby','auction'].includes(room.phase)?'<button class="btn small admin-trigger" data-action="admin">⚙ Ajustar OVR</button>':''}<button class="btn small ghost" data-action="bracket" ${['lobby','auction'].includes(room.phase)?'hidden':''}>Tabela e chave</button><button class="btn small ghost" data-action="leave">Sair</button></div></div>`;}
function rosterPanel(m){const hidden=hiddenRatings();return `<section class="panel roster-panel"><div class="roster-title"><h3>${m?.id===myId?'Sua line-up':esc(m.name)}</h3><span>${Object.keys(m.roster).length}/5</span></div><div class="wallet"><span>Orçamento restante</span><strong><span class="coin">R</span>${m.balance}</strong></div>${ROLES.map(r=>{const p=catalog.get(m.roster[r]);return `<div class="slot">${p?photo(p,'slot-photo'):`<span class="slot-role">${r}</span>`}<div><strong>${p?esc(p.name):'Vaga aberta'}</strong><small>${r} · ${p?esc(TEAM[p.team]):'Só entra se você comprar'}</small></div>${p?`<button class="value" data-player="${p.id}" aria-label="Detalhes de ${esc(p.name)}">${hidden?'?':p.overall}</button>`:''}</div>`;}).join('')}</section>`;}
function logPanel(){return `<section class="panel log-panel"><h3>Na sala</h3><div class="log">${[...room.log].reverse().slice(0,8).map(x=>`<p>${esc(x.text)}</p>`).join('')||'<p>Aguarde o primeiro lance.</p>'}</div></section>`;}
function lobby(){return `<div class="lobby-grid"><section class="panel"><div class="row-between"><div><h3>O lobby está aberto.</h3><p class="muted">Todo mundo começa com as mesmas 50 moedas.</p></div><span class="badge">${room.members.length}/${room.capacity}</span></div><div class="lobby-people">${room.members.map(m=>`<div class="team-seat"><div class="team-avatar">${initials(esc(m.name))}</div><div><strong>${esc(m.name)} ${m.id===myId?'· você':''}</strong><small>${m.bot?'Bot de treino':m.id===room.host?'Criador da sala':'Pronto para o draft'} · 50 moedas</small></div>${isHost()&&m.id!==room.host?`<button class="iconbtn" data-kick="${m.id}" aria-label="Remover ${esc(m.name)}">×</button>`:''}</div>`).join('')}${Array.from({length:room.capacity-room.members.length},()=>`<div class="team-seat empty">Aguardando a próxima equipe</div>`).join('')}</div></section><section class="panel lobby-settings"><div><h3>Como vai funcionar</h3><div class="rules-list"><div class="rule-row"><span class="rule-icon">◇</span><div><strong>Compre as cinco posições</strong>TOP, jungle, mid, ADC e suporte. Sem lance, a carta volta ao mercado.</div></div><div class="rule-row"><span class="rule-icon">◷</span><div><strong>10 segundos para decidir</strong>O maior lance leva. Reserve moedas para todas as vagas.</div></div><div class="rule-row"><span class="rule-icon">✦</span><div><strong>Dois drafts. Uma escolha.</strong>Escolha uma composição a cada jogo. Campeões usados não voltam na série.</div></div></div></div>${isHost()?`<div><label class="field">Tamanho do campeonato<select id="lobbyCapacity" aria-label="Tamanho do campeonato">${[2,4,8].map(n=>`<option value="${n}" ${n===room.capacity?'selected':''} ${n<room.members.length?'disabled':''}>${n} equipes</option>`).join('')}</select></label>${configControls(room.config,room.capacity)}<button class="btn outline wide" style="margin-top:12px" data-action="addbot" ${room.members.length>=room.capacity?'disabled':''}>Adicionar um bot</button></div><button class="btn primary wide" data-action="start">Começar o leilão</button><p class="field-note">Ao começar, vagas vazias recebem bots. Depois disso ninguém mais entra no campeonato.</p>`:`${configControls(room.config,room.capacity,true)}<div class="hint-box">O criador vai iniciar o leilão. Seu convite continua funcionando enquanto o lobby estiver aberto.</div>`}</section></div>`;}
function auction(){const a=room.auction,p=catalog.get(a.card),m=me(),limit=maxBid(room,m,p),isLeader=a.leader===myId;return `<div class="room-layout"><div class="room-main"><div class="sectionbar"><h3>Na mesa de negociação <span class="market-counter">${room.market?.pool.length||43} cartas</span></h3><div class="phase-tabs"><span class="current">Leilão</span><span>Draft</span><span>Taça</span></div></div><div class="auction-panel"><div class="auction-card"><div class="card-sup"><span class="rating-num">${hiddenRatings()?'?':p.overall}<small>${p.role}</small></span><span class="team-tag">${p.team}</span></div><div class="auction-portrait">${photo(p)}</div><strong class="player-name">${esc(p.name)}</strong><span class="player-meta">${esc(TEAM[p.team])} · CBLOL 2026</span>${stats(p)}</div><div class="bid-area"><div><div class="clock-row"><span class="eyebrow">CARTA EM LEILÃO</span><span class="clock" data-clock="${a.ends}">10<small>s</small></span></div><div class="progress"><i data-progress="${a.ends}" data-length="${Math.max(1,a.ends-(a.startedAt||a.ends-10000))}" style="width:100%"></i></div></div><div><span class="eyebrow">${a.bid?'LANCE ATUAL':'LANCE INICIAL'}</span><div class="bid-value"><span class="coin">R</span>${a.bid||1}<small>moedas fictícias</small></div><div class="leader">${a.leader?`Na frente: <b>${esc(teamName(a.leader))}</b>`:'A mesa está aberta. Faça seu lance.'}</div></div><div><div class="bid-buttons"><button class="btn primary" data-bid="${a.bid+1}" ${isLeader||limit<=a.bid?'disabled':''}>${isLeader?'Seu lance lidera':m.roster[p.role]?'Posição preenchida':'Dar lance · '+(a.bid+1)}</button><button class="btn outline" data-action="pass" ${a.passed.includes(myId)?'disabled':''}>${a.passed.includes(myId)?'Passou':'Passar'}</button></div><form class="bid-custom" id="customBid" style="margin-top:9px"><input id="bidAmount" type="number" min="${a.bid+1}" max="${limit}" value="${Math.min(limit,a.bid+3)}" aria-label="Valor do lance" ${limit<=a.bid||isLeader?'disabled':''}><button class="btn small ghost" ${limit<=a.bid||isLeader?'disabled':''}>Lance personalizado</button></form></div><p class="bid-hint">${m.roster[p.role]?'Sua posição de '+p.role+' já está fechada.':`Seu teto neste lote: ${limit} moedas. Uma moeda fica reservada para cada vaga aberta.`}</p>${a.lastBids.length?`<div class="recent-bids">${a.lastBids.slice(0,2).map(x=>`<span>${esc(x.name)} · ${x.amount}</span>`).join('')}</div>`:''}<p class="bid-hint no-auto">Sem lance, ninguém entra no seu time.</p><button class="text-btn" data-player="${p.id}" style="text-align:left">Detalhes da carta</button></div></div><div class="lineup-row">${ROLES.map(role=>`<div class="lineup-preview"><small>${role}</small><strong>${m.roster[role]?esc(catalog.get(m.roster[role]).name):'Em aberto'}</strong></div>`).join('')}</div><div class="room-activity"><div class="row-between"><h3 style="font-size:16px">De olho na concorrência</h3>${isHost()?'<button class="text-btn" data-action="speed">Encerrar lote agora</button>':''}</div><div class="opponents expanded-opponents">${room.members.filter(x=>x.id!==myId).map(x=>`<div class="opponent-roster"><div class="opponent-meta"><strong>${esc(x.name)}</strong><span>${Object.keys(x.roster).length}/5 · ${x.balance} moedas</span></div><div class="opponent-five">${ROLES.map(r=>{const c=catalog.get(x.roster[r]);return `<div title="${r} · ${c?esc(c.name):'Vazio'}" class="opponent-slot ${c?'owned':''}">${c?photo(c,'opponent-photo'):`<small>${r}</small>`}<span>${c?esc(c.name):r}</span></div>`;}).join('')}</div></div>`).join('')}</div></div></div><aside class="side-stack">${rosterPanel(m)}${logPanel()}</aside></div>`;}
function matchHead(){const m=room.matches[room.matchIndex],t=room.series;return `<div class="matchhead"><div><div class="name">${esc(teamName(m.a))}</div><small>${m.a===myId?'Sua equipe':'Adversário'}</small></div><div><div class="score">${m.score.join(' : ')}</div><div class="game-dots">${[1,2,3].map(n=>`<i class="${n<=m.games.length?'done':''}"></i>`).join('')}</div><small>MD3 · Jogo ${t.game} · vence quem chegar a 2</small></div><div><div class="name">${esc(teamName(m.b))}</div><small>${m.b===myId?'Sua equipe':'Adversário'}</small></div></div>`;}
function champions(comp){return `<div class="champions">${ROLES.map(r=>`<div class="champ-slot"><img class="champ-img" src="${champ(comp.champions[r])}" alt="${champName(comp.champions[r])}" loading="lazy"><small>${r}</small><strong>${champName(comp.champions[r])}</strong></div>`).join('')}</div>`;}
function draft(){const t=room.series,m=room.matches[room.matchIndex],mine=[m.a,m.b].includes(myId),chosen=t.choices[myId]!==undefined,opponent=m.a===myId?m.b:m.a;const renderOptions=(id,own)=>`<div class="comp-grid ${own?'':'opponent-options'}">${t.offers[id].map((c,i)=>{const st=style(c.style);return `<article class="comp-card ${own&&(t.myChoice===i||(selectedComp?.match===t.match&&selectedComp.game===t.game&&selectedComp.option===i))?'selected':''}"><div class="comp-body"><div class="tag">${st.tag}</div><h3>${st.name}</h3><p class="draft-source">${esc(c.team)} vs ${esc(c.opponent)} · ${esc(c.stage)} · Jogo ${c.game}<br><a href="${esc(c.source)}" target="_blank" rel="noreferrer">${esc(c.event)} · composição real</a></p>${champions(c)}<div class="comp-weights">${room.config.gameplay==='mechanical'?`Postura ${({engage:'Iniciar',control:'Proteger',pick:'Poke',scale:'Farmar'})[c.style]}: +4% dano · viagem e visão decidem`:`Coesão +${compBonus(c).toFixed(1)} · ${Math.round(st.micro*100)}% micro / ${Math.round(st.macro*100)}% macro / ${Math.round(st.mental*100)}% mental`}</div></div>${own?`<button class="btn" data-choice="${i}" ${chosen?'disabled':''}>${chosen?'Escolha confirmada':'Escolher composição '+(i+1)}</button>`:'<div class="secret-choice">Escolha oculta até a partida começar</div>'}</article>`;}).join('')}</div>`;return `${matchHead()}${opponentLineups()}<div class="draft-heading"><span class="eyebrow">DRAFTS REAIS · CBLOL E WORLDS · 10 SEGUNDOS</span><h2 style="margin-top:10px">${mine&&!chosen?'Qual é a sua chamada?':mine?'Sua composição está confirmada.':'Leia as possibilidades dos dois lados.'}</h2><p>Veja as duas opções adversárias. A opção escolhida só aparece quando a partida começar.</p></div>${mine?renderOptions(myId,true):renderOptions(m.a,false)}<div class="opponent-draft-title"><span class="eyebrow">${mine?'AS DUAS POSSIBILIDADES DE '+esc(teamName(opponent)):esc(teamName(m.b))}</span><span class="badge">${t.choices[opponent]!==undefined?'Escolha confirmada · oculta':'Escolhendo'}</span></div>${renderOptions(mine?opponent:m.b,false)}<div class="row-between" style="margin-top:18px"><span class="tagline">Fearless: campeões escolhidos não voltam nesta MD3.</span><span class="clock" data-clock="${t.deadline}" style="font-size:22px"></span></div>${t.used.length?`<div class="used-champs"><span>Bloqueados</span>${t.used.map(c=>`<img src="${champ(c)}" alt="${champName(c)} bloqueado">`).join('')}</div>`:''}`;}
function mapSVG(){return `<svg viewBox="0 0 800 440" aria-hidden="true"><defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#96acff" stroke-width=".3" opacity=".14"/></pattern><radialGradient id="bg"><stop stop-color="#263b79"/><stop offset="1" stop-color="#111f45"/></radialGradient></defs><rect width="800" height="440" fill="url(#bg)"/><rect width="800" height="440" fill="url(#grid)"/><path d="M190 350 190 90 610 90 610 350 190 350 610 90" fill="none" stroke="#685ac8" stroke-width="12" opacity=".2" stroke-linejoin="round"/><path d="M210 370 590 70" stroke="#63d8ed" stroke-width="28" opacity=".12"/><path d="m250 275 40-60 35 5-30 75z m135-85 55-40 15 45-45 20z m90 90 40-65 40 20-25 60z" fill="#6252ae" opacity=".15"/><circle cx="190" cy="350" r="23" fill="#5bdae4" opacity=".7"/><circle cx="610" cy="90" r="23" fill="#ff997f" opacity=".7"/><circle cx="325" cy="260" r="15" stroke="#a0a8f8" fill="none" opacity=".5"/><circle cx="480" cy="175" r="15" stroke="#a0a8f8" fill="none" opacity=".5"/>${[[190,160],[265,90],[530,90],[610,280],[510,350],[270,350],[330,250],[475,185]].map(([x,y])=>`<rect x="${x}" y="${y}" width="8" height="8" rx="2" fill="#8bb2f6" opacity=".5"/>`).join('')}</svg>`;}
function live(){const t=room.series,events=t.liveEvents||[],latest=events.at(-1),match=room.matches[room.matchIndex],center=[latest?.x||49,latest?.y||49];const coords=Array.from({length:10},(_,i)=>[Math.max(20,Math.min(78,center[0]+(i<5?-5:5)+(i%5-2)*2.3)),Math.max(16,Math.min(79,center[1]+(i<5?5:-5)+(i%3-1)*3))]);const obj=latest?.objectives||{};return `${matchHead()}<div class="selected-drafts"><div><strong>${esc(teamName(match.a))} · ${style(t.previewComps[0].style).name}</strong>${champions(t.previewComps[0])}</div><div><strong>${esc(teamName(match.b))} · ${style(t.previewComps[1].style).name}</strong>${champions(t.previewComps[1])}</div></div><div class="arena event-${latest?.kind||'fight'}">${mapSVG()}<div class="arena-top"><span>SUMMONER’S RIFT · SIMULAÇÃO</span><span>${latest?.time||'00:00'}</span></div><div class="objective-ring" style="left:${center[0]}%;top:${center[1]}%"></div>${coords.map(([x,y],i)=>`<img class="arena-pin ${i>4?'enemy':''}" style="left:${x}%;top:${y}%" src="${champ(t.previewComps[i>4?1:0].champions[ROLES[i%5]])}" alt="${champName(t.previewComps[i>4?1:0].champions[ROLES[i%5]])}">`).join('')}<span class="map-label baron-label">BARÃO / LARVAS</span><span class="map-label dragon-label">DRAGÕES</span><div class="arena-status"><strong>${esc(latest?.title||'Entrando no Rift')}</strong><span>${latest?`${esc(teamName(latest.gold>=0?match.a:match.b))} +${Math.abs(latest.gold).toLocaleString('pt-BR')} ouro`:''}</span></div></div><div class="objective-score">${[match.a,match.b].map(id=>`<div><strong>${esc(teamName(id))}</strong><span>${obj[id]?.kills||0} abates · ${obj[id]?.grubs||0} larvas · ${obj[id]?.dragons||0} dragões · ${obj[id]?.barons||0} Barões · ${obj[id]?.elders||0} Anciões</span></div>`).join('')}</div><div class="timeline">${events.slice(-4).reverse().map(e=>`<div class="event-row kind-${e.kind}"><time>${e.time}</time><div><strong>${esc(e.title)}</strong><p>${esc(e.text)}</p></div></div>`).join('')}</div><div class="inline-actions" style="justify-content:space-between"><span class="tagline">${events.length}/${t.eventTotal||'?'} acontecimentos · cada partida segue outro roteiro.</span>${isHost()?'<button class="text-btn" data-action="speed">Pular animação</button>':''}</div>`;}
function result(){if(room.series.result.mode==='mechanical')return renderTacticalResult(room,teamName,matchHead(),myId);const t=room.series,r=t.result,m=room.matches[room.matchIndex],winner=teamName(r.winner),loser=room.members.find(x=>x.id===(r.winner===m.a?m.b:m.a));return `${matchHead()}<div class="panel result-panel"><div class="trophy">✦</div><span class="eyebrow">NEXUS DESTRUÍDO</span><h2 style="margin-top:10px">${esc(winner)} venceu.</h2><p>${r.mvp} em destaque · ${r.duration} minutos de jogo simulado</p><div class="result-metrics"><div><b>${r.kills.join(' : ')}</b><small>ABATES</small></div><div><b>${Math.round(r.probability*100)}%</b><small>CHANCE PRÉ-JOGO DE ${esc(teamName(m.a))}</small></div></div><div class="analysis-box"><strong>Por que a partida foi assim?</strong><br>Força do elenco com draft: ${r.powers[0].toFixed(1)} × ${r.powers[1].toFixed(1)}. ${r.matchup?`A interação entre estilos somou ${Math.abs(r.matchup)} pontos ao ${r.matchup>0?'primeiro':'segundo'} time.`:'Os estilos não deram vantagem adicional.'} O sorteio decide a partir dessa chance; o favorito pode perder.<br><br><strong>O mental entra na próxima.</strong> ${esc(loser.name)} recebe uma queda de rendimento proporcional a (100 − mental). Vencer recupera até 2 pontos.${m.winner?' A MD3 terminou; o rendimento zera no próximo confronto.':''}<div class="penalty-list">${ROLES.map(role=>{const p=catalog.get(loser.roster[role]);return `<span>${esc(p.name)}: ${(loser.penalties[p.id]||0).toFixed(1)} rendimento</span>`;}).join('')}</div></div>${isHost()?`<button class="btn primary" data-action="next">${m.winner?'Concluir MD3':'Ir para o próximo draft'}</button>`:'<p>O criador pode avançar ou aguarde o relógio.</p>'}<p class="help-note">Avanço automático em <span data-clock="${t.deadline}"></span>. A série termina quando uma equipe vence dois jogos. Não existe terceiro jogo após 2 a 0.</p></div>`;}
function tournament(){return `<div class="room-layout"><div class="room-main"><div class="sectionbar"><h3>${matchLabel(room.matches[room.matchIndex])}</h3><span class="badge">Melhor de 3 · Fearless</span></div>${room.series.stage==='draft'?draft():room.series.stage==='live'?live():room.series.stage==='tactics'?renderTactics(room,myId,teamName,matchHead()):result()}</div><aside class="side-stack">${rosterPanel(me())}${logPanel()}</aside></div>`;}
function roundName(round,n){const left=n/2**(round-1);return left===2?'Grande final':left===4?'Semifinais':'Quartas de final';}
function bracket(){if(!room.matches.length)return '<p class="empty">A chave aparece quando as line-ups fecharem.</p>';const keys=[...new Set(room.matches.map(m=>(m.stage||'playoffs')+'-'+m.round+(m.group||'')))];return `${room.config.format!=='knockout'?`<h3>Classificação</h3>${room.groups?tableView('A')+tableView('B'):tableView()}<p class="help-note">3 pontos por MD3 vencida. Desempates: saldo de jogos, jogos ganhos e ordem do sorteio inicial.</p>`:''}<div class="bracket">${keys.map(key=>{const matches=room.matches.filter(m=>(m.stage||'playoffs')+'-'+m.round+(m.group||'')===key);return `<div class="bracket-round"><h4>${matchLabel(matches[0])}</h4>${matches.map(m=>`<div class="match-card ${room.series?.match===m.id?'active':''}">${[m.a,m.b].map((id,i)=>`<div class="match-team ${m.winner===id?'winner':''}"><span>${esc(teamName(id))}</span><strong>${m.score[i]}</strong></div>`).join('')}</div>`).join('')}</div>`;}).join('')}</div>`;}
function finished(){const winner=room.members.find(m=>m.id===room.champion),profile=getRank(me()?.name),entry=profile.history.find(x=>x.room===`${room.code}:${room.created}:${myId}`);return `<section class="champion-panel"><span class="eyebrow">O RIFT TEM UM NOVO DONO</span><div class="trophy" style="font-size:55px;margin-top:20px">♜</div><h1>${esc(winner.name)}</h1><p>${winner.id===myId?'Sua chamada trouxe a taça.':'Uma line-up. Boas chamadas. Uma taça.'} Campeão do Rift Draft.</p><div class="rank-reward ${entry?.delta>0?'positive':'negative'}"><span>RESULTADO RANQUEADO</span><strong>${entry?`${entry.place}º / ${entry.total} · ${entry.delta>0?'+':''}${entry.delta} PDL`:'Campeonato encerrado'}</strong><small>${rankLabel(profile)} · ${profile.lp} PDL · ${profile.titles} títulos</small></div><div class="rank-list"><span>${winner.spent} moedas investidas</span><span>${room.matches.filter(m=>m.winner===winner.id).length} confrontos vencidos</span><span>${room.members.length} equipes no campeonato</span></div><div class="champion-lineup">${ROLES.map(r=>playerTile(catalog.get(winner.roster[r]))).join('')}</div><button class="btn primary" data-action="new">Jogar um novo campeonato</button><button class="btn ghost" style="margin-left:8px" data-action="bracket">Ver a campanha</button></section>`;}
function render(){if(!room){home();return;}const scene=room.phase+':'+(room.series?.stage||'')+':'+(room.series?.game||'')+':'+(room.series?.tactics?.phase||'');const changedPhase=lastPhase!==scene;lastPhase=scene;const focus=document.activeElement;const saved=focus?.tagName==='INPUT'?{id:focus.id,value:focus.value,start:focus.selectionStart,end:focus.selectionEnd}:null;$('app').innerHTML=shell()+(room.phase==='lobby'?lobby():room.phase==='auction'?auction():room.phase==='tournament'?tournament():finished());if(saved&&$(saved.id)){const el=$(saved.id);el.value=saved.value;el.focus({preventScroll:true});try{el.setSelectionRange(saved.start,saved.end);}catch{}}clocks();if(changedPhase&&!$('modal').open)window.scrollTo({top:0,behavior:'instant'});}
function clocks(){document.querySelectorAll('[data-clock]').forEach(el=>{const sec=Math.max(0,Math.ceil((Number(el.dataset.clock)-now())/1000));el.innerHTML=sec+(el.classList.contains('clock')?'<small>s</small>':'s');el.classList.toggle('urgent',sec<=3);});document.querySelectorAll('[data-progress]').forEach(el=>el.style.width=Math.min(100,Math.max(0,100*(Number(el.dataset.progress)-now())/Number(el.dataset.length||10000)))+'%');}
function setRoom(s){const previous=room;room=s;syncRatings(s);updateAudio(s,now);if(s.phase==='finished'){const earned=applyRankResult(s,myId);if(earned){effect(earned.place===1?'champion':'loss');toast(`${earned.place}º de ${earned.total} · ${earned.delta>0?'+':''}${earned.delta} PDL · ${earned.rank}`,earned.delta<0);}}refreshRankHeader();if(previous?.phase==='auction'&&s.phase==='auction'&&previous.auction.card===s.auction.card&&previous.auction.leader===myId&&s.auction.leader!==myId&&s.auction.bid>previous.auction.bid){effect('outbid');toast('Cobriram seu lance! '+teamName(s.auction.leader)+' ofereceu '+s.auction.bid+'.');}if(previous?.phase==='auction'&&s.phase==='auction'&&previous.auction?.card===s.auction?.card&&s.auction.bid>previous.auction.bid&&s.auction.leader!==myId&&previous.auction.leader!==myId)effect('rivalBid');if(previous?.sold?.length<s.sold?.length)effect('sold');if(previous?.series?.liveEvents?.length<s.series?.liveEvents?.length&&['baron','elder','steal','soul'].includes(s.series.liveEvents.at(-1)?.kind))effect('objective');const key=JSON.stringify(s);if(signature!==key){signature=key;render();lastLog=s.logId;}}
async function request(path,body){const headers={};if(body!==undefined)headers['Content-Type']='application/json';if(token)headers.Authorization='Bearer '+token;const response=await fetch(path,{method:body===undefined?'GET':'POST',headers,body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json().catch(()=>({error:'O servidor não respondeu. Tente novamente.'}));if(!response.ok)throw new Error(data.error||'Não foi possível concluir.');if(data.serverNow)offset=data.serverNow-Date.now();return data;}
function keepSession(code){if(local){store.set('rift-training',{raw,id:myId});store.set('rift-last',{local:true,code});}else{store.set('rift-session-'+code,{id:myId,token});store.set('rift-last',{local:false,code});}const u=new URL(location.href);u.searchParams.set('sala',local?'treino':code);history.replaceState(null,'',u);}
function getName(){const name=($('teamName')?.value||store.get('rift-name')||'').trim().slice(0,24);if(!name){$('teamName')?.focus();throw new Error('Dê um nome à sua equipe para começar.');}store.set('rift-name',name);return name;}
async function create(localMode){if(busy)return;const name=getName();busy=true;$('createRoomBtn')?.classList.add('busy');try{local=localMode;offset=0;if(local){myId='you';token=null;raw=createRoom('TREINO',myId,name,crypto.getRandomValues(new Uint32Array(1))[0]);raw.capacity=capacity;raw.config={...roomConfig};room=null;setRoom(publicState(raw,myId));}else{token=null;const r=await request('/api/rooms',{name,capacity,config:roomConfig});myId=r.id;token=r.token;setRoom(r.state);}keepSession(room.code);toast(local?'Treino local pronto. Comece quando quiser.':'Sala criada! Copie o convite e chame seus amigos.');}catch(e){local=false;toast(e.message,true);$('createRoomBtn')?.classList.remove('busy');}finally{busy=false;}}
function parseCode(value){try{if(value.includes('://'))value=new URL(value).searchParams.get('sala')||'';}catch{}const c=value.trim().toUpperCase();if(!/^[A-Z2-9]{6}$/.test(c))throw new Error('Use o código de 6 caracteres ou o link do convite.');return c;}
async function join(code,name){if(busy)return;busy=true;try{local=false;const session=store.get('rift-session-'+code);token=session?.token||null;const r=await request('/api/rooms/'+code+'/join',{name});myId=r.id;token=r.token||token;setRoom(r.state);keepSession(code);toast('Você entrou na sala.');}finally{busy=false;}}
async function act(payload){if(busy||!room)return;if(payload.type==='bid')payload.card=room.auction.card;if(payload.type==='orders'){payload.match=room.series.match;payload.game=room.series.game;payload.turn=room.series.tactics.turn;}if(payload.type==='choose'){payload.match=room.series.match;payload.game=room.series.game;}busy=true;try{if(local){action(raw,myId,payload);setRoom(publicState(raw,myId));keepSession(room.code);}else{const r=await request('/api/rooms/'+room.code+'/action',payload);setRoom(r.state);}if(payload.type==='bid')effect('bid');if(payload.type==='rating')effect('choose');}catch(e){toast(e.message,true);}finally{busy=false;}}
async function poll(){if(!room||polling||busy||document.hidden)return;polling=true;try{if(local){tick(raw);setRoom(publicState(raw,myId));store.set('rift-training',{raw,id:myId});}else{const data=await request('/api/rooms/'+room.code);setRoom(data.state);}}catch(e){if(!poll.lastError||Date.now()-poll.lastError>20000){toast(e.message,true);poll.lastError=Date.now();}}finally{polling=false;}}
function modal(html,eyebrow='RIFT DRAFT'){const box=$('modal');$('modalEyebrow').textContent=eyebrow;$('modalContent').innerHTML=html;if(!box.open)box.showModal();}
function showCatalog(){modal(`<h2>As cartas do campeonato.</h2><p class="muted" style="margin-top:8px">43 jogadores que atuaram no Split 2 de 2026. Clique para ver os dados.</p><div class="catalog-tools"><div class="filters">${['ALL',...ROLES].map(r=>`<button class="filter ${r===catalogRole?'active':''}" data-filter="${r}">${r==='ALL'?'Todos':r}</button>`).join('')}</div><input id="catalogSearch" placeholder="Buscar jogador ou equipe" aria-label="Buscar jogador ou equipe" value="${esc(search)}"></div><div id="catalogGrid" class="catalog-grid"></div>`,'CATÁLOGO · CBLOL 2026');catalogResults();}
function catalogResults(){const players=PLAYERS.filter(p=>(catalogRole==='ALL'||p.role===catalogRole)&&`${p.name} ${TEAM[p.team]}`.toLowerCase().includes(search.toLowerCase()));$('catalogGrid').innerHTML=players.sort((a,b)=>b.overall-a.overall).map(playerTile).join('')||'<p class="empty">Nenhuma carta com esse filtro.</p>';}
function showPlayer(id){const p=catalog.get(id);if(!p)return;if(hiddenRatings()){modal(`<div class="detail-head">${photo(p,'detail-photo')}<div><h2>${esc(p.name)}</h2><p>${esc(TEAM[p.team])} · ${p.role}</p></div></div><p class="muted">Overall, atributos e valor de referência ficam ocultos durante este leilão por escolha do criador. As notas aparecem quando os times estiverem fechados.</p>`,'NOTAS OCULTAS');return;}modal(`<div class="detail-head">${photo(p,'detail-photo')}<div><h2>${esc(p.name)}</h2><p>${TEAM[p.team]} · ${p.role}</p></div><span class="rating-num">${p.overall}<small>GERAL</small></span></div><div class="detail-stats">${['mental','macro','micro'].map(k=>`<div class="detail-stat"><b>${p[k]}</b><span>${k[0].toUpperCase()+k.slice(1)}</span></div>`).join('')}</div><p class="statline">Índice de forma da equipe: <strong>${p.teamForm}</strong> · desempenho coletivo entra nas três notas.</p><p class="statline"><strong>${p.price} moedas</strong> de referência. Todo lote abre em 1; quem decide o preço é o leilão.</p><table class="data-table"><thead><tr><th>Amostra</th><th>Jogos</th><th>KDA</th><th>KP</th><th>DPM</th></tr></thead><tbody>${[['Fase regular',p.regular],['Playoffs',p.playoffs]].filter(([_,d])=>d).map(([n,d])=>`<tr><td>${n}</td><td>${d.games}</td><td>${d.kda.toFixed(1)}</td><td>${d.kp}%</td><td>${d.dpm}</td></tr>`).join('')}</tbody></table><p class="statline">Peso dos playoffs: <strong>${Math.round(p.recentWeight*100)}%</strong> na base de métricas. ${p.confidence<1?'Amostra pequena: nota aproximada da média da posição.':'Comparação com jogadores da mesma posição.'}</p><p class="muted">Mental é um índice de jogo baseado em mortes e KDA. Não mede a saúde mental, personalidade ou capacidade emocional real do jogador.</p><div class="inline-actions"><button class="btn outline" data-action="method">Entender os cálculos</button><button class="btn ghost" data-action="catalog">Ver todas as cartas</button></div>`,'CARTA · DADOS REAIS, ATRIBUTOS ESTIMADOS');}
function rules(){modal(`<h2>Compre seu time. Vença a MD3.</h2><div class="prose"><h3>Compras, sem contratações automáticas</h3><p>Cada técnico começa com 50 moedas. Você precisa comprar uma carta por posição: TOP, JG, MID, ADC e SUP. Só o maior lance confirmado recebe a carta. Sem lance, ela volta ao mercado; nenhuma moeda é cobrada e nenhum jogador entra no seu time.</p><p>Cada lote abre com 10 segundos. Todo novo lance reinicia o relógio em 3 segundos, visíveis no painel. Uma moeda fica reservada para cada posição aberta. Um lance que chegar depois do lote é recusado, nunca aplicado à carta seguinte.</p><h3>Três mercados</h3><p>O criador escolhe a quantidade exata de cartas para as vagas, essa quantidade +12 ou todos os 43 jogadores. O mercado sempre tem cartas suficientes por função. Se +12 ultrapassar o catálogo, a sala mostra o limite real. Cartas não vendidas continuam disponíveis; o criador pode recolocá-las em um lote sem lances pelo botão Mercado.</p><h3>Formatos</h3><p><strong>Mata-mata:</strong> eliminação direta. <strong>Pontos corridos:</strong> todos contra todos uma vez; campeão pela tabela. <strong>Liga + playoffs:</strong> todos contra todos e os melhores vão ao mata-mata (quatro entre oito equipes, dois entre quatro). <strong>Grupos + mata-mata:</strong> dois grupos; oito equipes classificam duas por grupo para semifinais cruzadas, quatro equipes classificam uma por grupo para a final.</p><p>Vitória de série vale 3 pontos. Desempate por saldo de jogos, jogos ganhos e posição no sorteio inicial, nessa ordem. Com duas equipes, a fase é um confronto direto.</p><h3>Melhor de três de verdade</h3><p>Quem vence dois jogos ganha o confronto. Uma MD3 pode terminar 2 a 0 ou 2 a 1. Não há terceiro jogo após 2 a 0.</p><h3>Draft da CBLOL ou Worlds, com Fearless</h3><p>O criador escolhe CBLOL 2026, Worlds 2026 ou misto. As duas opções de cada lado são composições reais de séries desses campeonatos. Você pode consultar a line-up e as duas opções do adversário. A escolha exata fica escondida até a partida começar. As quatro alternativas são compatíveis entre si; campeões escolhidos por qualquer lado não voltam na MD3. Alternativas não escolhidas podem aparecer depois.</p><p>Ao escolher, os campeões animam e um acorde confirma o draft. O relógio de 10 segundos escolhe automaticamente uma opção somente se o técnico não confirmar.</p><h3>Sons e dinâmica</h3><p>Os efeitos sonoros têm controle no topo; a música de fundo foi removida. O som começa após sua primeira interação e pode ser desligado a qualquer momento. Se cobrirem seu lance, um aviso próprio toca. Avisos curtos tocam nos dois segundos finais do lote.</p><p>A simulação comenta invasões, ganks, larvas, dragões, Arauto, Barão, lutas nas laterais, possíveis roubos e Ancião em jogos longos. O mapa acompanha o lugar de cada acontecimento. É uma simulação fictícia, não uma reprodução de partida profissional.</p><h3>Automático ou Mecânico</h3><p>O criador escolhe o modo no lobby. No Automático, os elencos e os drafts definem probabilidades e a partida é simulada. No Mecânico, os técnicos movem os cinco campeões, escolhem posturas e builds e confirmam planos escondidos. Ambos executam juntos. Visão, alcance, viagem e controle de objetivos decidem; o vencedor não é sorteado. As regras completas estão no mapa.</p><h3>Mental e recuperação</h3><p>Derrotas reduzem o rendimento conforme o atributo mental; vitórias recuperam até 2 pontos, com penalidade acumulada limitada a −8. O efeito zera em cada nova MD3.</p><p>Jogo independente inspirado em <strong>Footlobby</strong>. Moedas são fictícias, sem apostas. Salas duram 24 horas; guarde o convite e use o mesmo navegador para retomar.</p></div>`,'COMO FUNCIONA');}
function method(){modal(`<h2>Balanceamento com contexto.</h2><div class="prose"><p>Base de jogadores: CBLOL 2026 Split 2, consultado em 21/11/2026. São 43 nomes que aparecem nas amostras, incluindo substitutos. As notas são estimativas para o jogo, sem vínculo com ranking oficial ou avaliação psicológica.</p><h3>Desempenho individual e coletivo</h3><p>Métricas são comparadas dentro de cada posição. Playoffs recebem peso w = jogos / (jogos + 8); o restante vem da fase regular. Amostras abaixo de 15 jogos são aproximadas da média. A escala foi comprimida para 64–88 antes da combinação, evitando abismos entre cartas.</p><div class="formula">Individual micro = 35% ouro@15 + 25% farm@15 + 25% dano/min + 15% KDA<br>Micro de SUP = 45% KDA + 35% KP + 20% poucas mortes<br>Individual macro = 55% KP + 45% visão/min<br>Individual mental = 60% poucas mortes + 40% KDA<br>Forma coletiva = 45% vitórias + 25% controle de dragões + 20% controle de Barão + 10% ouro@15<br>Micro final = 80% individual + 20% coletivo<br>Macro final = 65% individual + 35% coletivo<br>Mental final = 75% individual + 25% coletivo<br>Overall = 40% micro + 40% macro + 20% mental</div><p>Os percentuais acima são pesos de percentis, não uma soma de unidades diferentes. KP significa participação em abates. Os resultados da equipe também são ponderados para playoffs. Preço de referência = 5 + (overall − 65) × 0,45, arredondado e limitado a 5–16. O leilão determina o preço real. Ajustes autorizados de OVR valem apenas na sala.</p><h3>Fontes das cartas</h3><p><a href="https://gol.gg/players/list/season-ALL/split-ALL/tournament-CBLOL%202026%20Split%202/" target="_blank" rel="noreferrer">Games of Legends · jogadores, fase regular</a><br><a href="https://gol.gg/players/list/season-ALL/split-ALL/tournament-CBLOL%202026%20Split%202%20Playoffs/" target="_blank" rel="noreferrer">Jogadores, playoffs</a><br><a href="https://gol.gg/teams/list/season-ALL/split-ALL/tournament-CBLOL%202026%20Split%202/" target="_blank" rel="noreferrer">Equipes, fase regular</a><br><a href="https://gol.gg/teams/list/season-ALL/split-ALL/tournament-CBLOL%202026%20Split%202%20Playoffs/" target="_blank" rel="noreferrer">Equipes, playoffs</a><br><a href="https://maisesports.com.br/cblol-2026-veja-o-que-mudou-nas-escalacoes-dos-times-para-o-2-split" target="_blank" rel="noreferrer">Mais Esports · escalações</a></p><h3>Fotos reais</h3><p>42 retratos vêm das escalações oficiais do LoL Esports, com crédito à Riot Games. Shini usa retrato histórico verificado de 2025 via Sheep Esports/Leaguepedia. Isso não altera a equipe exibida no recorte de 2026. Cada origem consta no código em player-photos.json.</p><h3>Drafts reais: CBLOL e Worlds</h3><p>São 50 composições do Worlds 2026 e 36 composições do CBLOL 2026 Split 2 (playoffs). Você escolhe a origem ao criar uma sala. Para garantir duas opções por técnico sem repetir campeões na MD3, a sala sorteia um conjunto Fearless de 8 a 10 drafts integralmente distintos das séries selecionadas do CBLOL ou Worlds. Cada cartão mostra time, confronto, jogo e link da tabela consultada.</p><p><a href="https://lol2llm.com/en/esports/worlds-2026-final-results" target="_blank" rel="noreferrer">Worlds 2026 · final</a><br><a href="https://lol2llm.com/en/esports/worlds-2026-knockout-stage-results" target="_blank" rel="noreferrer">Worlds 2026 · mata-mata</a></p><p>Os picks e as posições são os reais. A classificação em iniciação, controle, pickoff e escalamento é nossa curadoria; não é uma nota oficial de patch nem de proficiência de cada jogador.</p><h3>Simulação</h3><div class="formula">Força = média ponderada das cinco cartas + rendimento + coesão<br>Chance A = 1 / (1 + exp(−diferença de força / 10))<br>Chances limitadas a 18%–82%<br>Após derrota: −(100 − mental) × 0,08 por carta<br>Vitória recupera +2, até zerar a penalidade</div><p>Os estilos mudam os pesos dos atributos. Iniciação supera pickoff, pickoff supera controle, controle supera escalamento e escalamento supera iniciação, com bônus de 2,5 pontos. Cada composição recebe coesão calculada pelas afinidades, enquanto os drafts do Worlds recebem +2, sem favorecer o vencedor histórico.</p><p>O servidor sorteia o resultado uma vez. A narrativa, os abates, o ouro e os objetivos são acontecimentos fictícios gerados para cada simulação; não são estatísticas da partida original do Worlds. Mental é uma mecânica de jogo, não diagnóstico. Inspirado em Footlobby, sem afiliação ao Footlobby, à Riot Games ou ao CBLOL.</p></div>`,'DADOS, FOTOS E BALANCEAMENTO');}
function adminPanel(preferred=null){if(!canEdit()){toast('Sem permissão de edição.',true);return;}const first=catalog.get(preferred||PLAYERS[0].id)||catalog.get(PLAYERS[0].id);modal(`<div class="admin-top"><h2>Painel de administração</h2><p class="muted">Ajustes de OVR para este campeonato, com acesso exclusivo do criador e dos editores autorizados. As notas entram nas partidas e afetam os atributos.</p></div><form id="adminRating" class="admin-form"><label class="field">Jogador<select id="ratingPlayer">${PLAYERS.map(p=>`<option value="${p.id}" ${first.id===p.id?'selected':''}>${esc(p.name)} · ${p.role} · ${esc(TEAM[p.team])}</option>`).join('')}</select></label><label class="field">Novo overall (40 a 99)<input id="ratingOverall" type="number" min="40" max="99" step="1" value="${first.overall}" required></label><button class="btn primary wide" type="submit">Salvar nota do jogador</button></form>${isHost()?`<section class="admin-team-editors"><h3>Delegar edição aos técnicos da sala</h3><p class="muted">Selecione qualquer equipe cadastrada nesta sala. A permissão é vinculada à sessão autenticada da equipe, não apenas ao nickname.</p>${room.members.filter(m=>!m.bot&&m.id!==room.host).map(m=>`<div class="admin-member"><strong>${esc(m.name)}</strong><button class="btn small outline" data-editor="${m.id}" data-enabled="${room.editors?.includes(m.id)?'false':'true'}">${room.editors?.includes(m.id)?'Revogar editor':'Tornar editor'}</button></div>`).join('')||'<p class="muted">Convide outra equipe humana para delegar.</p>'}</section>`:''}<p class="field-note">Alterações são guardadas na sala e ficam bloqueadas ao encerrar o leilão. Não afetam as notas oficiais dos jogadores nem outras salas.</p>`,'ADMIN · NOTAS DO CAMPEONATO');}
function profilePanel(){const name=me()?.name||store.get('rift-name')||'Equipe',r=getRank(name);modal(`<div class="rank-identity"><span class="rank-symbol">◆</span><div><span class="eyebrow">SEU PERFIL RANQUEADO</span><h2>${esc(name)}</h2></div></div><div class="rank-details"><span><b>${r.wins} - ${r.losses}</b><small>campanhas</small></span><span><b>${rankLabel(r)}</b><small>divisão atual</small></span><span><b>${r.titles}</b><small>títulos</small></span></div><div class="rank-track"><div style="width:${rankPercent(r)}%"></div></div><p class="muted" style="margin:10px 0 24px">${r.lp}/100 PDL até a próxima divisão. Ganhar é mais valioso; um vice perde menos PDL do que cair cedo.</p><h3>Últimos campeonatos</h3><div class="rank-history">${r.history.map(x=>`<div><span>${new Date(x.date).toLocaleDateString('pt-BR')} · ${x.place}º/${x.total}</span><strong class="${x.delta>0?'good':'bad'}">${x.delta>0?'+':''}${x.delta} PDL</strong></div>`).join('')||'<p class="muted">Conclua seu primeiro campeonato para receber PDL.</p>'}</div><p class="field-note">O perfil é salvo neste navegador por nome da equipe. Não há contas ou ranking global entre dispositivos.</p>`,'RANKED · PERFIL');}
function teams(){modal(`<h2>Os times da sala.</h2><div class="lobby-people">${room.members.map(m=>`<div>${rosterPanel(m)}</div>`).join('')}</div>`,'LINE-UPS');}
async function resume(){const saved=store.get('rift-last');if(!saved)return;if(saved.local){const p=store.get('rift-training');if(!p?.raw)throw new Error('Treino não encontrado. Comece outro.');local=true;offset=0;raw=p.raw;myId=p.id;tick(raw);setRoom(publicState(raw,myId));keepSession(raw.code);}else{const s=store.get('rift-session-'+saved.code);if(!s)throw new Error('Sessão não encontrada neste navegador.');local=false;token=s.token;myId=s.id;const data=await request('/api/rooms/'+saved.code);setRoom(data.state);keepSession(saved.code);}}
async function handleAction(name){switch(name){case'home':case'leave':room=null;raw=null;updateAudio(null,now);signature='';history.replaceState(null,'',location.pathname);home();break;case'new':room=null;raw=null;updateAudio(null,now);history.replaceState(null,'',location.pathname);home();break;case'catalog':showCatalog();break;case'close':$('modal').close();break;case'rules':rules();break;case'method':method();break;case'practice':await create(true);break;case'join':{const code=parseCode($('inviteCode').value),name=getName();await join(code,name);break;}case'resume':await resume();break;case'copy':{const link=new URL(location.href);link.searchParams.set('sala',room.code);try{await navigator.clipboard.writeText(link.href);toast('Convite copiado. Manda no grupo!');}catch{modal(`<h2>Convide sua tropa.</h2><label class="field" style="margin-top:20px">Copie este link<input value="${esc(link.href)}" readonly aria-label="Link do convite"></label>`);}break;}case'teams':teams();break;case'admin':adminPanel();break;case'profile':profilePanel();break;case'bracket':modal('<h2>Tabela e caminho até a taça.</h2>'+bracket(),'CAMPEONATO');break;case'market':marketModal();break;case'alerts':setAudio('alerts',!audioState().alerts);audioButtons();break;case'addbot':case'start':case'pass':case'next':case'speed':await act({type:name});break;}}
document.addEventListener('click',async e=>{if(room?.series?.stage==='tactics'){try{if(e.target.closest('[data-tactic-commit]')){unlockAudio();effect('choose');await act({type:'orders',orders:tacticalPayload()});return;}if(tacticsClick(e,room,myId,render))return;}catch(err){toast(err.message,true);return;}}const b=e.target.closest('button');if(!b||b.disabled)return;unlockAudio();try{if(b.dataset.action)await handleAction(b.dataset.action);else if(b.dataset.player)showPlayer(b.dataset.player);else if(b.dataset.capacity){capacity=+b.dataset.capacity;document.querySelectorAll('[data-capacity]').forEach(x=>{x.classList.toggle('selected',+x.dataset.capacity===capacity);x.setAttribute('aria-pressed',+x.dataset.capacity===capacity);});if($('marketCount'))$('marketCount').textContent=marketSize(capacity,roomConfig.supply)+' cartas para '+capacity*5+' vagas';}else if(b.dataset.bid)await act({type:'bid',amount:+b.dataset.bid});else if(b.dataset.choice){selectedComp={match:room.series.match,game:room.series.game,option:+b.dataset.choice};b.closest('.comp-card')?.classList.add('picking');pickAnimation(room.series.offers[myId][+b.dataset.choice]);effect('choose');await act({type:'choose',option:+b.dataset.choice});}else if(b.dataset.editor){await act({type:'editor',memberId:b.dataset.editor,enabled:b.dataset.enabled==='true'});adminPanel();}else if(b.dataset.reoffer){await act({type:'reoffer',card:b.dataset.reoffer});$('modal').close();}else if(b.dataset.kick)await act({type:'kick',id:b.dataset.kick});else if(b.dataset.filter){catalogRole=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x.dataset.filter===catalogRole));catalogResults();}}catch(err){toast(err.message,true);}});
document.addEventListener('submit',async e=>{e.preventDefault();try{if(e.target.id==='setupForm'){unlockAudio();await create(false);}if(e.target.id==='customBid')await act({type:'bid',amount:Number($('bidAmount').value)});if(e.target.id==='adminRating'){const playerId=$('ratingPlayer').value;await act({type:'rating',playerId,overall:Number($('ratingOverall').value)});adminPanel(playerId);}}catch(err){toast(err.message,true);}});
document.addEventListener('change',e=>{if(room?.series?.stage==='tactics'&&tacticsChange(e,room,myId,render))return;if(e.target.id==='lobbyCapacity')act({type:'capacity',value:Number(e.target.value)});if(e.target.id==='ratingPlayer')$('ratingOverall').value=catalog.get(e.target.value)?.overall||75;const key={gameplayMode:'gameplay',supplyMode:'supply',formatMode:'format',draftPool:'draftPool',showOverall:'showOverall'}[e.target.id];if(key){const value=key==='showOverall'?e.target.checked:e.target.value;if(room?.phase==='lobby')act({type:'config',config:{[key]:value}});else{roomConfig[key]=value;if($('marketCount'))$('marketCount').textContent=marketSize(capacity,roomConfig.supply)+' cartas para '+capacity*5+' vagas';}}});document.addEventListener('input',e=>{if(e.target.id==='catalogSearch'){search=e.target.value;catalogResults();}});$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const rect=$('modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)$('modal').close();}});
setInterval(clocks,200);setInterval(poll,1500);document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});home();
const query=new URL(location.href).searchParams.get('sala');if(query){if(query==='treino'){const saved=store.get('rift-last');if(saved?.local)resume().catch(e=>toast(e.message,true));}else if(store.get('rift-session-'+query)){local=false;token=store.get('rift-session-'+query).token;myId=store.get('rift-session-'+query).id;request('/api/rooms/'+query).then(data=>setRoom(data.state)).catch(e=>toast(e.message,true));}else toast('Convite recebido. Dê um nome ao time e clique em Entrar.');}

function marketModal(){const cards=(room.market?.pool||[]).map(id=>catalog.get(id)).filter(p=>!room.sold.includes(p.id));modal(`<h2>Mercado da sala</h2><p class="muted">${SUPPLY_NAMES[room.config.supply]} · ${cards.length} cartas ainda sem comprador. Carta sem lance continua disponível.</p><div class="catalog-grid" style="margin-top:22px">${cards.map(p=>`<div>${playerTile(p)}${isHost()&&room.auction.bid===0&&room.members.some(m=>!m.roster[p.role])?`<button class="btn small outline wide" data-reoffer="${p.id}">Leiloar ${esc(p.name)}</button>`:''}</div>`).join('')}</div>`,'SÓ ENTRA QUEM VOCÊ COMPRAR');}
function audioButtons(){const a=audioState();document.querySelectorAll('[data-action="alerts"]').forEach(b=>{b.textContent=a.alerts?'🔊 Efeitos ligados':'🔇 Efeitos desligados';b.setAttribute('aria-pressed',a.alerts);});}
const audioBar=document.createElement('div');audioBar.className='audio-controls';audioBar.innerHTML='<button data-action="alerts" type="button"></button>'; document.querySelector('.topbar').append(audioBar);const rankButton=document.createElement('button');rankButton.type='button';rankButton.className='top-rank';rankButton.id='rankProfile';rankButton.dataset.action='profile';document.querySelector('.topbar').append(rankButton);audioButtons();refreshRankHeader();

function pickAnimation(comp){const el=document.createElement('div');el.className='draft-lock-overlay';el.setAttribute('aria-hidden','true');el.innerHTML=`<div><span>COMPOSIÇÃO CONFIRMADA</span><strong>${style(comp.style).name}</strong><div class="lock-champs">${ROLES.map((r,i)=>`<img style="--delay:${i*65}ms" src="${champ(comp.champions[r])}" alt="">`).join('')}</div></div>`;document.body.append(el);setTimeout(()=>el.remove(),1100);}
